{
  "facts": [
    {
      "topic": "scope",
      "statement": "The target reads PNG data through the sequential reader: it calls png_read_info, png_read_update_info, png_start_read_image, then png_read_row for each pass and row.",
      "evidence": [
        {
          "unit_id": "u-e9cdca141412a92154b2",
