          "end_line": 179,
          "role": "primary",
          "dependency_reason": ""
        }
      ]
    ,
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "On both source versions, png_read_update_info calls png_read_start_row when PNG_FLAG_ROW_INIT is clear and reports a duplicate call when it is set.",
      "evidence": [
        {
          "unit_id": "u-b53e493521e3901bcbc1",
