    },
    {
      "topic": "contract",
      "statement": "On both source versions, png_start_read_image calls png_read_start_row when PNG_FLAG_ROW_INIT is clear; when the flag is set, it calls png_app_error for a duplicate call.",
      "evidence": [
        {
          "unit_id": "u-4a3ce9d69b27b864372c",
